import org.jetbrains.kotlin.gradle.dsl.JvmTarget
import javax.inject.Inject

// A testee for protobuf's official conformance suite: `conformance_test_runner`, built by
// build-runner.sh from the protobuf release matching the protobuf version, sends it binary test
// messages, which it decodes and re-encodes with code generated by protoc-gen-protomorphic-kotlin.
// JSON, text format and proto2 tests are skipped. Run with `runConformanceSuite`.
plugins {
    alias(libs.plugins.kotlinJvm)
    application
    id("studio.dabble.protomorphic")
}

// protobuf-java 4.x matches protobuf release x.y.
val protobufRelease = libs.versions.protobuf.get().substringAfter('.')

repositories {
    mavenCentral()
    exclusiveContent {
        forRepository {
            ivy {
                name = "protobufReleases"
                url = uri("https://github.com/protocolbuffers/protobuf/releases/download")
                patternLayout { artifact("v[revision]/[module]-[revision].[ext]") }
                metadataSources { artifact() }
            }
        }
        filter { includeModule("protocolbuffers", "protobuf") }
    }
}

val protobufSource: Configuration by configurations.creating { isTransitive = false }
dependencies {
    protobufSource("protocolbuffers:protobuf:$protobufRelease@tar.gz")
}

abstract class ExtractProtos @Inject constructor(
    private val fileSystem: FileSystemOperations,
    private val archives: ArchiveOperations,
) : DefaultTask() {
    @get:InputFiles @get:PathSensitive(PathSensitivity.NONE) abstract val source: ConfigurableFileCollection
    @get:Input abstract val paths: MapProperty<String, String>
    @get:Input abstract val droppedLines: Property<String>
    @get:OutputDirectory abstract val outputDir: DirectoryProperty

    @TaskAction
    fun extract() {
        val wanted = paths.get()
        fileSystem.sync {
            from(archives.tarTree(archives.gzip(source.singleFile)))
            include { it.isDirectory || it.relativePath.segments.drop(1).joinToString("/") in wanted }
            eachFile { path = wanted.getValue(relativePath.segments.drop(1).joinToString("/")) }
            val dropped = Regex(droppedLines.get())
            filter { line -> if (dropped.containsMatchIn(line)) "" else line }
            includeEmptyDirs = false
            into(outputDir)
        }
    }
}

val testProtos by tasks.registering(ExtractProtos::class) {
    source.from(protobufSource)
    paths = mapOf(
        "src/google/protobuf/test_messages_proto3.proto" to "google/protobuf/test_messages_proto3.proto",
        "editions/golden/test_messages_proto3_editions.proto" to "editions/golden/test_messages_proto3_editions.proto",
    )
    // The generator does not support FieldMask; without these fields their values are kept as
    // unknown fields, which still round-trip.
    droppedLines = """^\s*(repeated )?google\.protobuf\.FieldMask """
    outputDir = layout.buildDirectory.dir("protos/test")
}

val conformanceProto by tasks.registering(ExtractProtos::class) {
    source.from(protobufSource)
    paths = mapOf("conformance/conformance.proto" to "conformance/conformance.proto")
    droppedLines = "^$^"
    outputDir = layout.buildDirectory.dir("protos/conformance")
}

protomorphic {
    useLocalProjects = true
    sourceDir = testProtos.flatMap { it.outputDir }
}

/** The runner's own request and response messages, with protobuf-java, so the harness does not depend on the code under test. */
abstract class GenerateJava @Inject constructor(private val exec: ExecOperations) : DefaultTask() {
    @get:InputFiles @get:PathSensitive(PathSensitivity.NONE) abstract val protoc: ConfigurableFileCollection
    @get:InputDirectory @get:PathSensitive(PathSensitivity.RELATIVE) abstract val protos: DirectoryProperty
    @get:OutputDirectory abstract val outputDir: DirectoryProperty

    @TaskAction
    fun generate() {
        val out = outputDir.get().asFile.apply { deleteRecursively(); mkdirs() }
        val protocExe = temporaryDir.resolve("protoc").also { protoc.singleFile.copyTo(it, overwrite = true); it.setExecutable(true) }
        val root = protos.get().asFile
        exec.exec {
            commandLine(
                listOf(protocExe.absolutePath, "--java_out=${out.absolutePath}", "-I${root.absolutePath}") +
                    root.walkTopDown().filter { it.extension == "proto" }.map { it.relativeTo(root).invariantSeparatorsPath }.sorted(),
            )
        }
    }
}

val conformanceJava by tasks.registering(GenerateJava::class) {
    protoc.from(configurations.named("protomorphicProtoc"))
    protos = conformanceProto.flatMap { it.outputDir }
    outputDir = layout.buildDirectory.dir("generated/conformance-java")
}

sourceSets.main {
    java.srcDir(conformanceJava)
}

kotlin {
    compilerOptions {
        jvmTarget = JvmTarget.JVM_17
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

dependencies {
    implementation(libs.protobuf.java)
}

application {
    mainClass = "studio.dabble.protomorphic.conformance.suite.TesteeKt"
}

// Needs a conformance_test_runner, built by build-runner.sh: -PconformanceRunner=<path>.
val runConformanceSuite by tasks.registering(Exec::class) {
    group = "verification"
    description = "Runs protobuf's conformance_test_runner against the testee, failing on tests not in failure_list.txt."
    dependsOn(tasks.installDist)
    val runner = providers.gradleProperty("conformanceRunner")
    val testee = layout.buildDirectory.file("install/conformance-suite/bin/conformance-suite")
    val failureList = layout.projectDirectory.file("failure_list.txt")
    val output = layout.buildDirectory.dir("conformance")
    inputs.file(failureList)
    doFirst { output.get().asFile.mkdirs() }
    executable(runner.orElse(provider { throw GradleException("Pass -PconformanceRunner=<path to conformance_test_runner>") }).get())
    argumentProviders.add(
        CommandLineArgumentProvider {
            listOf(
                "--maximum_edition", "2023",
                "--failure_list", failureList.asFile.absolutePath,
                "--output_dir", output.get().asFile.absolutePath,
                testee.get().asFile.absolutePath,
            )
        },
    )
}
